"""Fill paragraphs of text into lines no wider than a given width."""
import re

_PARAGRAPH_BREAK = re.compile(r"\n\s*\n")


def wrap(text, width):
    """Return text filled greedily to width, with paragraphs separated by one empty line.

    Blank lines separate paragraphs. Within a paragraph all whitespace collapses to single
    spaces. A word longer than width goes on its own line, unbroken; words are never split.
    """
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError(f"width must be an integer of at least 1, got {width!r}")
    lines = []
    for paragraph in _PARAGRAPH_BREAK.split(text):
        words = paragraph.split()
        if not words:
            continue
        if lines:
            lines.append("")
        line = ""
        for word in words:
            if not line:
                line = word
            elif len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                lines.append(line)
                line = word
        lines.append(line)
    return "\n".join(lines)

